/**
 * O sonar do golfinho — porte de `componentes/viz/sonar.js`.
 *
 * O calombo na testa do golfinho — o melão — é uma lente ACÚSTICA: ele muda a
 * forma para focar os cliques num feixe estreito, como uma lente de vidro faz com
 * a luz. Focado longe demais, o feixe chega largo e a imagem borra; focado perto,
 * ele converge antes do alvo e reabre. No ponto, o golfinho "vê" a presa pelo som
 * na escuridão total.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const sonar: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const foco = Math.max(0, numeroDe(valores, 'f', 0));
    const alvo = numeroDe(info, 'alvo', 62);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Uma lente feita de gordura');

    const golfinhoX = L * 0.16;
    const golfinhoY = A * 0.54;
    const presaX = L * 0.82;
    // A presa fica no eixo do feixe, e não no meio do canvas: fora do eixo o
    // encontro nunca pareceria exato.
    const presaY = golfinhoY - 7;

    // O golfinho de perfil.
    const gc = golfinhoX + 4;
    ctx.fillStyle = cor.fraco;
    ctx.beginPath();
    ctx.moveTo(gc + 44, golfinhoY + 2);
    ctx.quadraticCurveTo(gc + 32, golfinhoY - 5, gc + 24, golfinhoY - 11);
    ctx.quadraticCurveTo(gc + 4, golfinhoY - 22, gc - 18, golfinhoY - 13);
    ctx.quadraticCurveTo(gc - 34, golfinhoY - 7, gc - 42, golfinhoY - 2);
    ctx.quadraticCurveTo(gc - 32, golfinhoY + 5, gc - 16, golfinhoY + 12);
    ctx.quadraticCurveTo(gc + 6, golfinhoY + 18, gc + 24, golfinhoY + 8);
    ctx.quadraticCurveTo(gc + 34, golfinhoY + 6, gc + 44, golfinhoY + 2);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(gc - 38, golfinhoY);
    ctx.lineTo(gc - 56, golfinhoY - 12);
    ctx.lineTo(gc - 48, golfinhoY);
    ctx.lineTo(gc - 56, golfinhoY + 12);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(gc - 4, golfinhoY - 15);
    ctx.quadraticCurveTo(gc - 16, golfinhoY - 30, gc - 20, golfinhoY - 14);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.moveTo(gc + 8, golfinhoY + 9);
    ctx.quadraticCurveTo(gc + 2, golfinhoY + 25, gc - 8, golfinhoY + 19);
    ctx.closePath();
    ctx.fill();

    // O melão — a lente.
    ctx.fillStyle = ok ? cor.verde : cor.contraste;
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.ellipse(gc + 26, golfinhoY - 7, 11, 9, -0.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.arc(gc + 20, golfinhoY - 3, 2.4, 0, Math.PI * 2);
    ctx.fill();

    // O feixe. O cruzamento é ancorado NA PRESA: no alvo ele fecha exatamente
    // sobre ela; abaixo, cruza depois; acima, cruza antes.
    const emiX = golfinhoX + 30;
    const emiY = golfinhoY - 7;
    const focoX = presaX + ((alvo - foco) / 100) * (L * 0.62);
    const abertura = 26;

    ctx.strokeStyle = ok ? cor.verde : cor.azulClaro;
    ctx.lineWidth = 1.5;
    for (let i = -3; i <= 3; i++) {
      const y0 = emiY + (i / 3) * abertura;
      ctx.beginPath();
      ctx.moveTo(emiX, y0);
      ctx.lineTo(focoX, emiY);
      const alem = L - focoX;
      ctx.lineTo(L, emiY - (i / 3) * abertura * (alem / Math.max(1, focoX - emiX)) * 0.5);
      ctx.stroke();
    }

    ctx.fillStyle = ok ? cor.verde : cor.azul;
    for (let i = 0; i < 4; i++) {
      const fase = (t * 0.8 + i / 4) % 1;
      ctx.beginPath();
      ctx.arc(emiX + fase * (presaX - emiX), emiY, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // A presa: uma só quando o feixe fecha nela, três fantasmas quando não.
    const borrao = (Math.abs(presaX - focoX) / L) * 60 + 2;
    ctx.fillStyle = ok ? cor.verde : cor.trilho;
    for (let g = 0; g < (ok ? 1 : 3); g++) {
      const desvio = ok ? 0 : (g - 1) * borrao * 0.5;
      ctx.beginPath();
      ctx.ellipse(presaX + desvio, presaY, 12, 7, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(presaX + desvio + 11, presaY);
      ctx.lineTo(presaX + desvio + 20, presaY - 6);
      ctx.lineTo(presaX + desvio + 20, presaY + 6);
      ctx.closePath();
      ctx.fill();
    }

    ctx.strokeStyle = cor.trilho;
    ctx.setLineDash([3, 3]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(focoX, A * 0.24);
    ctx.lineTo(focoX, A * 0.8);
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, 'foco', focoX, A * 0.24 - 9, limitar(A * 0.034, 8, 11), { cor: cor.fraco });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Feixe focado na presa: nitidez pelo som ✔',
      'Ajuste o melão até o feixe convergir na presa.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default sonar;
